export type Booking = { id: number; lab: string };
export abstract class BookingRepo {
  abstract find(id: number): Booking | undefined;
  abstract save(b: Booking): void;
}
export class BookingService {
  #repo: BookingRepo;
  constructor(repo: BookingRepo) { this.#repo = repo; }
  book(id: number, lab: string): Booking { const b: Booking = { id, lab }; this.#repo.save(b); return b; }
  find(id: number): Booking | undefined { return this.#repo.find(id); }
}

import { BookingRepo, type Booking } from './service.ts';
export class MemoryRepo extends BookingRepo {
  #rows = new Map<number, Booking>();
  find(id: number): Booking | undefined { return this.#rows.get(id); }
  save(b: Booking): void { this.#rows.set(b.id, b); }
}

import type { Booking } from '../src/service.ts';
import { BookingService } from '../src/service.ts';
import { MemoryRepo } from '../src/memory.ts';
const b: Booking = { id: 1, lab: 'BE-201' };
const svc = new BookingService(new MemoryRepo());
export const made: Booking = svc.book(2, 'CS-101');
export { b };

import type { Booking } from '../src/service.ts';
import { BookingService, BookingRepo } from '../src/service.ts';
import { MemoryRepo } from '../src/memory.ts';
export const s1 = new BookingRepo(); // expect TS2511
export const s2: Booking = { id: 1 }; // expect TS2741
export const s3: Booking = { id: '1', lab: 'x' }; // expect TS2322
export const s4 = new BookingService(new MemoryRepo()).#repo; // expect TS18013

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { BookingService } from '../src/service.ts';
import { MemoryRepo } from '../src/memory.ts';
test('books through the repo and finds it back', () => { const svc = new BookingService(new MemoryRepo()); const b = svc.book(1, 'BE-201'); assert.equal(b.lab, 'BE-201'); assert.equal(svc.find(1)?.lab, 'BE-201'); assert.equal(svc.find(9), undefined); });

